abbrev ExactSectionSpace (S : Set E) (K : Set F) (H : P → Submodule ℝ F) :=
  {t : P × (E →L[ℝ] F) // Function.Injective t.2 ∧
    LinearMap.range t.2.toLinearMap = H t.1 ∧ t.2 '' S = K ∩ (H t.1 : Set F)}

